      },
      "stakes_shift": "From a simple looter to a high-profile criminal wanted by the city guard.",
      "title": "Grand Theft Artifact"
    },
    {
      "bridge": {
        "from_prev": "The narrow escape from the city gates.",
        "to_next": "Artie discovers a hidden sanctuary that holds the truth about his class's origin."
      },
      "chapter_id": 4,
      "chapter_role": "journey",
      "goal": "Artie navigates the 'Dead Zones'\u2014areas where the System is buggy\u2014to lose his pursuers.",
      "pacing": {
        "expected_scene_count": 12,
        "intensity": 4,
        "tempo": "rush"
      },
      "stakes_shift": "From fleeing a local guard to surviving a hostile, reality-warping environment.",
      "title": "The Glass Cannon Run"
    },
    {
      "bridge": {
        "from_prev": "The discovery of the sanctuary is interrupted by the bounty hunter's arrival.",
        "to_next": "Artie wins but realizes the bounty hunter was just the scout for a larger guild."
      },
      "chapter_id": 5,
      "chapter_role": "trial",
      "goal": "A professional bounty hunter with a 'Nullification' build corners Artie, forcing him to fight without his exploits.",
      "pacing": {
        "expected_scene_count": 9,
        "intensity": 4,
        "tempo": "steady"
      },
      "stakes_shift": "From relying on glitches to proving his core tactical competence as a player.",
      "title": "Optimization or Extinction"
    },
    {
      "bridge": {
        "from_prev": "The need to finalize his build before the 'System Sentinels' catch up.",
        "to_next": "The boss falls, but the resulting explosion of data alerts the entire world to Artie's location."
      },
      "chapter_id": 6,
      "chapter_role": "climax",
      "goal": "Artie raids the regional boss's lair to secure a permanent 'Stability Patch' item, facing overwhelming odds.",
      "pacing": {
        "expected_scene_count": 12,
        "intensity": 5,
        "tempo": "rush"
      },
      "stakes_shift": "From a hunted anomaly to a potential power player in the world's meta-narrative.",
      "title": "The One-Percent Chance"
    },
    {
      "bridge": {
        "from_prev": "The defeat of the regional boss and the acquisition of the Stability Patch.",
        "to_next": "Artie sets his sights on the capital to find the source of the System's code."
      },
      "chapter_id": 7,
      "chapter_role": "aftermath",
      "goal": "Artie secures his loot and escapes into the next region just as the System initiates a 'Zone Reset'.",
      "pacing": {
        "expected_scene_count": 8,
        "intensity": 2,
        "tempo": "slow_burn"
      },
      "stakes_shift": "From a local glitch to a global phenomenon that the System itself is trying to delete.",
      "title": "Outrunning the Patch Notes"
    }
  ],
  "schema_version": "spine_v1"
}

